package framework

// This is a static list of configuration fields. Every choice remains editable.
const webAlgorithmChoices = "0=Clear|129=DES-OFB|130=2-key 3DES — Not implemented|131=3-key 3DES|132=AES-256|133=AES-128 — Not implemented|137=AES-128-OFB — Not implemented|159=DES-XL — Not implemented|170=ADP"

func webSections() []webSection {
	return []webSection{
		{Path: "system", Title: "System Configuration", Role: RoleSystem, Fields: []webField{
			{Name: "id", Label: "System record ID", Kind: "text", Help: "Names this system in service configuration and connections."},
			{Name: "name", Label: "System name", Kind: "text"},
			{Name: "wacn", Label: "WACN (decimal)", Kind: "number", Help: "Identifies the radio network. Enter the decimal value stored by the system."},
			{Name: "system_id", Label: "P25 System ID (decimal)", Kind: "number", Help: "Identifies the P25 system within the network."},
			{Name: "callsign", Label: "Callsign", Kind: "text", Help: "Station callsign used for identification."},
			{Name: "voice_mfid", Label: "Generated voice MFID (decimal)", Kind: "number", Help: "Sets the Manufacturer ID carried by voice generated here."},
			{Name: "bsi_profile", Label: "BSI signaling profile", Kind: "select", Choices: "motorola=Motorola|harris=Harris — Not implemented", Help: "Selects the station identification message format."},
		}},
		{Path: "radios", Title: "Radio Directory", Collection: "radios", Role: RoleSystem, Fields: []webField{
			{Name: "rid", Label: "Radio / Unit ID (decimal)", Kind: "number", Help: "Individual identity programmed into the radio."},
			{Name: "group", Label: "Group", Kind: "record-combo", Help: "Internal directory group. Choose an existing name or type a new one. Example: Fire. Save keeps the entered name."},
			{Name: "alias", Label: "Name", Kind: "user-alias", Help: "Caller name sent during Phase 1 trunked calls and shown in the directory. Use 1–14 printable ASCII characters, for example Engine 12. The receiving radio must support User Alias."},
			{Name: "kind", Label: "Type", Kind: "select", Choices: "subscriber=Subscriber radio|console=Dispatch console|mobile=PTT application|automation=Automation client"},
			{Name: "enabled", Label: "System access enabled", Kind: "bool", Help: "Controls this identity's access to the system."},
		}},
		{Path: "talkgroups", Title: "Talkgroups", Collection: "talkgroups", Role: RoleSystem, Fields: []webField{
			{Name: "tgid", Label: "Talkgroup ID (decimal)", Kind: "number", Help: "Group identity programmed into participating radios."},
			{Name: "alias", Label: "Name", Kind: "text"},
			{Name: "group", Label: "Group", Kind: "record-combo", Help: "Internal directory group. Choose an existing name or type a new one. Example: Public Works. Save keeps the entered name."},
			{Name: "enabled", Label: "Enabled", Kind: "bool"},
			{Name: "affiliation_access", Label: "Radio affiliation", Kind: "select", Choices: "all=All subscriber radios|selected=Selected radios", Help: "Controls which radios may join the group to receive its calls."},
			{Name: "affiliation_radio_ids", Label: "Affiliation Radio IDs (comma separated)", Kind: "numbers"},
			{Name: "transmit_access", Label: "Radio transmit permission", Kind: "select", Choices: "all=All subscriber radios|selected=Selected radios", Help: "Controls which radios may originate calls on the group."},
			{Name: "transmit_radio_ids", Label: "Transmit Radio IDs (comma separated)", Kind: "numbers"},
			{Name: "site_access", Label: "Site access", Kind: "select", Choices: "all=All Sites|selected=Selected Sites", Help: "Controls the Sites where this group may operate."},
			{Name: "site_ids", Label: "Site record IDs (comma separated)", Kind: "strings"},
			{Name: "start_policy", Label: "Call start", Kind: "select", Choices: "fast_start=FASTStart|all_start=AllStart", Help: "FASTStart begins with the first available destination. AllStart waits briefly for the required destinations."},
			{Name: "priority", Label: "Routine call priority", Kind: "number", Help: "Lower numbers receive higher call priority."},
			{Name: "admission_mode", Label: "Secure Communication Mode", Kind: "select", Choices: "clear=Clear only|secure=Encrypted only|both=Clear and encrypted", Help: "Sets the kinds of calls the system accepts on this talkgroup."},
			{Name: "transmit_mode", Label: "Transmit strapping", Kind: "select", Choices: "clear=Clear|secure=Encrypted|selectable=Operator selectable", Help: "Sets outgoing Dispatch, PTT and announcement calls. Operator selectable uses the requested clear or encrypted mode."},
			{Name: "algorithm_id", Label: "Transmit algorithm", Kind: "select-number", Choices: webAlgorithmChoices, Help: "Selects the assigned outgoing encryption key. Received calls use their own algorithm and Key ID."},
			{Name: "key_id", Label: "Transmit Key ID (decimal)", Kind: "number", Help: "Identifies the assigned outgoing traffic key within the selected algorithm."},
		}},
		{Path: "status-labels", Title: "Status Labels", Collection: "status_labels", Role: RoleSystem, Fields: []webField{
			{Name: "id", Label: "Status number (decimal)", Kind: "number", Help: "Received status value to label."},
			{Name: "label", Label: "Meaning", Kind: "text"},
		}},
		{Path: "message-labels", Title: "Message Labels", Collection: "message_labels", Role: RoleSystem, Fields: []webField{
			{Name: "id", Label: "Message number (decimal)", Kind: "number", Help: "Received message code to label."},
			{Name: "label", Label: "Meaning", Kind: "text"},
		}},
		{Path: "positions", Title: "Console Positions", Collection: "console_positions", Role: RoleSystem, Fields: []webField{
			{Name: "id", Label: "Position record ID", Kind: "text"},
			{Name: "name", Label: "Position name", Kind: "text"},
			{Name: "radio_id", Label: "Console Radio ID (decimal)", Kind: "number", Help: "Radio identity used by this dispatch position."},
			{Name: "enabled", Label: "Enabled", Kind: "bool"},
			{Name: "talkgroups", Label: "Talkgroup IDs (comma separated)", Kind: "numbers", Help: "Groups assigned to this position."},
		}},
		{Path: "zone", Title: "Zone Configuration", Role: RoleZone, Fields: []webField{
			{Name: "id", Label: "Zone record ID", Kind: "text"},
			{Name: "system_id", Label: "System record ID", Kind: "text", Help: "Names the System Administration record used by this Zone."},
			{Name: "name", Label: "Zone name", Kind: "text"},
			{Name: "rfss_id", Label: "RFSS ID (decimal)", Kind: "number", Help: "Identifies this radio subsystem within the P25 system."},
		}},
		{Path: "identifiers", Title: "Band Plan", Collection: "channel_identifiers", Role: RoleZone, Fields: []webField{
			{Name: "identifier", Label: "Band Plan ID (decimal)", Kind: "number", Help: "P25 Channel Identifier (0–15) broadcast by the Site. The same ID has the same frequency meaning throughout the system."},
			{Name: "base_frequency_hz", Label: "Base frequency (MHz)", Kind: "number", Help: "Reference frequency used with spacing and channel number. Example: 443.4375 MHz."},
			{Name: "channel_spacing_hz", Label: "Channel spacing (kHz)", Kind: "number", Help: "Frequency step between consecutive channel numbers. Example: 12.5 kHz."},
			{Name: "uplink_offset_hz", Label: "Subscriber transmit offset (MHz)", Kind: "number", Help: "Signed difference from Site transmit to subscriber transmit frequency. Example: +5 MHz."},
			{Name: "bandwidth_hz", Label: "Bandwidth (kHz)", Kind: "number"},
		}},
		{Path: "sites", Title: "Sites", Collection: "sites", Role: RoleZone, Fields: []webField{
			{Name: "id", Label: "Site record ID", Kind: "text", Help: "Names the Site Controller in service configuration and connections."},
			{Name: "name", Label: "Site name", Kind: "text"},
			{Name: "site_id", Label: "P25 Site ID (decimal)", Kind: "number"},
			{Name: "lra", Label: "Location Registration Area (LRA)", Kind: "number", Help: "Identifies a location registration area shared by one or more Sites within this System. For example, use LRA 1 on two Sites in the same location registration area. The P25 field is one octet. Actual roaming requires separate radio qualification."},
			{Name: "nac", Label: "Network Access Code / NAC (decimal)", Kind: "number", Help: "Network access value used on this Site's RF channels."},
			{Name: "endpoint", Label: "Internal service address", Kind: "text", Help: "HTTP address used by services over the internal VPN."},
			{Name: "admin_url", Label: "Administration address", Kind: "text", Help: "Web address used to open this Site's administration pages."},
		}},
		{Path: "modems", Title: "Modems", Collection: "modems", Role: RoleSite, Fields: []webField{
			{Name: "id", Label: "Modem record ID", Kind: "text"},
			{Name: "name", Label: "Modem name", Kind: "text"},
			{Name: "device", Label: "USB device path", Kind: "text", Help: "Existing stable USB identity path for this modem."},
			{Name: "baud", Label: "Serial baud rate (baud)", Kind: "number"},
			{Name: "calibration.rx_offset_hz", Label: "Receive frequency correction (Hz)", Kind: "number"},
			{Name: "calibration.tx_offset_hz", Label: "Transmit frequency correction (Hz)", Kind: "number"},
			{Name: "calibration.rx_level", Label: "Receive level (%)", Kind: "number"},
			{Name: "calibration.tx_level", Label: "Transmit level (%)", Kind: "number"},
			{Name: "calibration.rx_dc_offset", Label: "Receive DC offset", Kind: "number"},
			{Name: "calibration.tx_dc_offset", Label: "Transmit DC offset", Kind: "number"},
			{Name: "calibration.rx_invert", Label: "Invert receive", Kind: "bool"},
			{Name: "calibration.tx_invert", Label: "Invert transmit", Kind: "bool"},
			{Name: "calibration.ptt_invert", Label: "Invert PTT", Kind: "bool"},
		}},
		{Path: "channels", Title: "RF Channels", Collection: "channels", Role: RoleSite, Fields: []webField{
			{Name: "id", Label: "Channel record ID", Kind: "text"},
			{Name: "name", Label: "Channel name", Kind: "text"},
			{Name: "role", Label: "Assigned role", Kind: "select", Choices: "control=Control|voice=Voice", Help: "Selects the initial assigned control channel when the Site starts. A manual switch, dynamic replacement or scheduled rotation changes the operating role without rewriting this saved assignment."},
			{Name: "control_eligible", Label: "Control eligible", Kind: "bool", Help: "Allows this channel to be promoted to control on its own configured frequency pair. Automatic selection uses only this Site's assigned channels; it does not claim unassigned hardware or another Site's modem. Edited eligibility takes effect on the next explicit Stop Site and Start Site."},
			{Name: "control_priority", Label: "Control selection order", Kind: "number", Help: "Orders eligible control candidates. Lower values are selected first; timed rotation moves through that order. Scheduled and manual switches wait until the whole Site is idle. Edited order takes effect on the next explicit Stop Site and Start Site."},
			{Name: "identifier", Label: "Band Plan ID (decimal)", Kind: "number", Help: "P25 Channel Identifier (0–15) matching the Zone Band Plan."},
			{Name: "channel_no", Label: "P25 channel number", Kind: "number", Help: "Position within the selected Band Plan. Site transmit = base + channel number × spacing. Site receive also includes the subscriber transmit offset."},
			{Name: "tx_frequency_hz", Label: "Site transmit frequency (MHz)", Kind: "derived-frequency"},
			{Name: "rx_frequency_hz", Label: "Site receive frequency (MHz)", Kind: "derived-frequency"},
			{Name: "power_percent", Label: "Transmit power (%)", Kind: "number"},
			{Name: "modem_id", Label: "Modem record ID", Kind: "text", Help: "Names the modem assigned to this channel."},
			{Name: "enabled", Label: "Enabled", Kind: "bool"},
		}},
		{Path: "control-policy", Title: "Control Channel Policy", Role: RoleSite, Fields: []webField{
			{Name: "broadcast_band_plan", Label: "Broadcast Band Plan", Kind: "bool", Help: "Send periodic Channel Identifier Updates on this Site’s control channel. Normally enabled. Turn off only to test radios with preprogrammed tables; other radios may be unable to follow calls. Takes effect after Stop Site and Start Site."},
			{Name: "control_policy.mode", Label: "Control assignment", Kind: "select", Choices: "static=Static assigned control|dynamic=Dynamic replacement", Help: "After a failure, Static retries the currently selected control channel. Dynamic may promote an eligible idle voice channel, retaining its frequency pair. The replacement remains control when the original modem recovers. Scheduled rotation and explicit manual switching are independent of this failure policy. Saved policy takes effect on the next explicit Stop Site and Start Site."},
			{Name: "control_policy.rotation_enabled", Label: "Scheduled control rotation", Kind: "bool", Help: "Periodically switches control among eligible channels in selection order. Scheduled and manual switches wait until all Site calls, allocations and identification have finished, then restart the RF workers on the new control channel. This is independent of automatic failure replacement. Saved policy takes effect on the next explicit Stop Site and Start Site."},
			{Name: "control_policy.rotation_hours", Label: "Rotation interval (hours)", Kind: "number", Help: "Elapsed time from the last successful control activation. For example, 24 rotates once per day of operation. Scheduled rotation waits until the whole Site is idle. Saved policy takes effect on the next explicit Stop Site and Start Site."},
		}},
		{Path: "site-identity", Title: "Local Site identity", Role: RoleSite, Fields: []webField{{Name: "id", Label: "Site record ID", Kind: "text", Help: "Local record identity. The Zone owns the P25 Site identity and Site registry."}}},
		{Path: "identification", Title: "Station Identification", Role: RoleSite, Fields: []webField{
			{Name: "enabled", Label: "Automatic identification enabled", Kind: "bool"},
			{Name: "mode", Label: "Identification mode", Kind: "select", Choices: "ham=CWID (Ham)|bsi=BSI (Commercial)"},
			{Name: "wpm", Label: "Morse speed (WPM)", Kind: "number"},
			{Name: "quiet_seconds", Label: "Quiet period (seconds)", Kind: "number", Help: "Quiet interval used before identifying a voice channel."},
		}},
		{Path: "application-settings", Title: "Application Server Configuration", Role: RoleApplication, Fields: []webField{
			{Name: "name", Label: "Application Server name", Kind: "text"},
			{Name: "connection_url", Label: "Controller address", Kind: "text", Help: "Internal HTTP address of the Zone or Site Controller."},
			{Name: "local_site_url", Label: "Local Site address", Kind: "text", Help: "Internal HTTP address of the local Site Controller."},
		}},
	}
}
